"""Development-only assembler. Release uses generated bytes and relocation records."""
from pathlib import Path
import struct,json,hashlib
from keystone import Ks,KS_ARCH_X86,KS_MODE_64
import research as R
from talents import GAME_SHA256

if hashlib.sha256(R.DATA).hexdigest()!=GAME_SHA256:
    raise RuntimeError('Refusing to build hooks for an unverified game executable')

BASE=0xaaa000000000;CTL=0xbbb000000000;CODE=0xccc000000000
TARGETS={0x21c0,0x21d0,0x5ba5190}
PATCH_RVAS={'tick':0x5ba08a0,'roll':0x5bfc1b0,'reroll':0x5c09880,'banish':0x5c05fc0,'god':0x5b90260,'kill':0x5bd6420,'recalc':0x5b9510a,'choices':0x5bfca8e,'leech':0x5ba1760,'treasure':0x5c04421,'treasure_min':0x5c05048}
SPECS={}
for key,rva in PATCH_RVAS.items():
    size=0
    for ins in R.MD.disasm(R.PE.get_data(rva,64),R.BASE+rva):
        size+=ins.size
        if size>=14:break
    SPECS[key]={'rva':rva,'original':R.PE.get_data(rva,size).hex()}

def hx(b):return '.byte '+','.join(hex(x) for x in b)
def far(rva):TARGETS.add(rva);return 'jmp qword ptr [rip]; .quad '+hex(BASE+rva)
def orig(key):
    d=SPECS[key];return hx(bytes.fromhex(d['original']))+';'+far(d['rva']+len(bytes.fromhex(d['original'])))
def guard(reg,end):
    return f'movabs r11,{CTL};cmp dword ptr [r11+12],1;jne {end};cmp {reg},qword ptr [r11];jne {end};mov eax,dword ptr [{reg}+0xbdc];cmp eax,dword ptr [r11+8];jb {end};'
save='pushfq;push rax;push rcx;push rdx;push r8;push r9;push r10;push r11;sub rsp,0x88;'
save+=';'.join(f'movdqu xmmword ptr [rsp+{0x20+i*16}],xmm{i}' for i in range(6))+';'
restore=';'.join(f'movdqu xmm{i},xmmword ptr [rsp+{0x20+i*16}]' for i in range(6))+';add rsp,0x88;pop r11;pop r10;pop r9;pop r8;pop rdx;pop rcx;pop rax;popfq;'
small='pushfq;push rax;push r11;'
small_restore='pop r11;pop rax;popfq;'
parts=[];markers={}
def entry(name,code):
    marker=0xddd000000000+len(markers)*0x100;markers[name]=marker
    parts.append('.quad '+hex(marker)+';'+name+':;'+code)

entry('tick',save+guard('rcx','tick_done')+'inc dword ptr [r11+60];call commands;call apply_values;movabs r11,'+str(CTL)+';cmp dword ptr [r11+24],0;je tick_done;movss xmm1,dword ptr [rsp+0x30];mulss xmm1,dword ptr [r11+28];movss dword ptr [rsp+0x30],xmm1;tick_done:;'+restore+orig('tick'))
entry('roll',save+guard('rcx','roll_done')+'call apply_values;inc dword ptr [r11+64];mov eax,dword ptr [rcx+0x4cc];mov dword ptr [r11+84],eax;roll_done:;'+restore+orig('roll'))
rer=small+guard('rcx','rer_done')+'cmp dword ptr [r11+0x108],0;je rer_done;mov eax,dword ptr [r11+0x208];test eax,eax;je rer_done;inc eax;mov dword ptr [rcx+0x568],eax;inc dword ptr [r11+68];rer_done:;'+small_restore
rer+='push rsi;push rbx;sub rsp,0x28;cmp byte ptr [rcx+0xc8a],2;je rer_valid;'+far(0x5c09967)+';rer_valid:;'+far(0x5c09893)
entry('reroll',rer)
entry('banish',small+guard('rcx','ban_done')+'cmp dword ptr [r11+0x10c],0;je ban_done;mov eax,dword ptr [r11+0x20c];test eax,eax;je ban_done;inc eax;mov dword ptr [rcx+0xc58],eax;inc dword ptr [r11+72];ban_done:;'+small_restore+orig('banish'))
entry('god',small+guard('rcx','god_original')+'cmp dword ptr [r11+16],0;je god_original;inc dword ptr [r11+76];'+small_restore+'ret;god_original:;'+small_restore+orig('god'))
entry('kill',small+guard('rcx','kill_done')+'cmp dword ptr [r11+20],0;je kill_done;movd eax,xmm2;test eax,eax;jle kill_done;cmp eax,0x7f800000;jae kill_done;mov eax,0x60ad78ec;movd xmm2,eax;inc dword ptr [r11+80];kill_done:;'+small_restore+orig('kill'))
# Recalc point: original terminal stores, then apply held cached properties before HP clamping.
recalc=hx(bytes.fromhex(SPECS['recalc']['original']))+';'+save.replace('sub rsp,0x88','sub rsp,0x80')+'mov rcx,rsi;'+guard('rcx','recalc_done')+'call apply_values;movss xmm12,dword ptr [rcx+0x4a0];recalc_done:;'+restore.replace('add rsp,0x88','add rsp,0x80')+far(SPECS['recalc']['rva']+len(bytes.fromhex(SPECS['recalc']['original'])))
entry('recalc',recalc)
entry('choices',small+guard('rdi','choices_original')+'cmp dword ptr [r11+32],0;je choices_original;mov eax,dword ptr [r11+36];mov qword ptr [rbp+0x138],rax;'+small_restore+far(0x5bfca9d)+';choices_original:;'+small_restore+orig('choices'))
leech=small+guard('rcx','leech_original')+'cmp dword ptr [r11+52],0;je leech_original;movss xmm0,dword ptr [r11+56];'+small_restore+'ret;leech_original:;'+small_restore
leech+='mov rax,qword ptr [rcx+0x60];test rax,rax;jne leech_more;'+far(0x5ba17e8)+';leech_more:;movss xmm1,dword ptr [rcx+0xbdc];'+far(0x5ba1771)
entry('leech',leech)

# Jewelry selection has its own loop and minimum-padding branch. Keep the
# original exhaustion/duplicate checks and alter only the two count thresholds.
treasure=small+'push rcx;mov rcx,qword ptr [rbp+0x168];'+guard('rcx','treasure_original')+'cmp dword ptr [r11+88],0;je treasure_original;mov eax,dword ptr [r11+92];dec eax;cmp rbx,rax;pop rcx;pop r11;pop rax;lea rsp,[rsp+8];'
treasure+=hx(bytes.fromhex(SPECS['treasure']['original'])[4:])+';'+far(0x5c04433)+';treasure_original:;pop rcx;'+small_restore+orig('treasure')
entry('treasure',treasure)
treasure_min=small+guard('r14','treasure_min_original')+'cmp dword ptr [r11+88],0;je treasure_min_original;mov eax,dword ptr [r11+92];cmp rsi,rax;jge treasure_min_done;'+small_restore+far(0x5c05052)+';treasure_min_done:;'+small_restore+far(0x5c050dc)+';treasure_min_original:;'+small_restore
treasure_min+='cmp rsi,3;jge treasure_min_orig_done;mov eax,dword ptr [r14+0xc34];'+far(0x5c05059)+';treasure_min_orig_done:;'+far(0x5c050dc)
entry('treasure_min',treasure_min)

# Stable registration indices shared with runtime_features: no overwritten instructions here.
offsets=[0x508,0x510,0x568,0xc58,0x4a0,0x4a4,0x4a8,0x4ac,0x4b0,0x4c0,0x4c4,0x4c8,0x4d4,0x4d8,0x4b4,0x4b8,0x4bc,0x4cc,0x4d0,0x4dc,0x50c,0x564,0x4e0,0x4e4,0x4e8,0x4ec]
apply='apply_values:;movabs r11,'+str(CTL)+';'
for i,off in enumerate(offsets):
    apply+=f'cmp dword ptr [r11+{0x100+i*4}],0;je av_{i};mov eax,dword ptr [r11+{0x200+i*4}];'
    if i==0:apply+='cmp eax,dword ptr [rcx+0x4a0];cmova eax,dword ptr [rcx+0x4a0];'
    apply+=f'mov dword ptr [rcx+{off}],eax;av_{i}:;'
for index,tag in enumerate([0x16,0x12]):
    apply+=f'cmp dword ptr [r11+{0x400+index*4}],0;je mod_end_{index};mov rdx,qword ptr [rcx+0x818];mov r8,qword ptr [rcx+0x820];xor r9d,r9d;xor r10d,r10d;mod_loop_{index}:;cmp r9,r8;jae mod_append_{index};cmp byte ptr [rdx+r9*8],{tag};jne mod_next_{index};test r10d,r10d;jne mod_zero_{index};mov eax,dword ptr [r11+{0x440+index*4}];mov dword ptr [rdx+r9*8+4],eax;mov r10d,1;jmp mod_next_{index};mod_zero_{index}:;mov dword ptr [rdx+r9*8+4],0;mod_next_{index}:;inc r9;jmp mod_loop_{index};mod_append_{index}:;test r10d,r10d;jne mod_end_{index};cmp r8,qword ptr [rcx+0x810];jae mod_grow_{index};mov qword ptr [rdx+r8*8],0;mov byte ptr [rdx+r8*8],{tag};mov eax,dword ptr [r11+{0x440+index*4}];mov dword ptr [rdx+r8*8+4],eax;inc r8;mov qword ptr [rcx+0x820],r8;jmp mod_end_{index};mod_grow_{index}:;mov dword ptr [r11+40],1;mod_end_{index}:;'
apply+='ret;'
parts.append(apply)

# Native-thread commands: reserve Mod Vec with the game's allocator, and settle manually-set XP.
cmd='commands:;push rbx;push r12;push r13;push r14;push r15;push rsi;push rdi;sub rsp,0x20;mov rbx,rcx;mov r12,r11;'
cmd+='cmp dword ptr [r12+40],1;jne cmd_xp;mov dword ptr [r12+40],0;mov rsi,qword ptr [rbx+0x820];mov r14,qword ptr [rbx+0x810];lea r15,[rsi+16];cmp r14,r15;jae grow_ok;cmp r15,0x1000;ja grow_fail;mov rcx,r15;shl rcx,3;mov edx,4;movabs rax,'+str(BASE+0x21c0)+';call rax;test rax,rax;je grow_fail;mov r13,rax;mov rdi,qword ptr [rbx+0x818];xor r10d,r10d;grow_copy:;cmp r10,rsi;jae grow_assign;mov rax,qword ptr [rdi+r10*8];mov qword ptr [r13+r10*8],rax;inc r10;jmp grow_copy;grow_assign:;mov qword ptr [rbx+0x810],r15;mov qword ptr [rbx+0x818],r13;test r14,r14;je grow_ok;mov rcx,rdi;mov rdx,r14;shl rdx,3;mov r8d,4;movabs rax,'+str(BASE+0x21d0)+';call rax;grow_ok:;mov dword ptr [r12+44],0;jmp cmd_xp;grow_fail:;mov dword ptr [r12+44],1;'
cmd+='cmd_xp:;cmp dword ptr [r12+48],1;jne cmd_done;cmp byte ptr [rbx+0xc8a],1;jne cmd_done;mov dword ptr [r12+48],0;mov rcx,rbx;xor edx,edx;movabs rax,'+str(BASE+0x5ba5190)+';call rax;cmd_done:;mov rcx,rbx;mov r11,r12;add rsp,0x20;pop rdi;pop rsi;pop r15;pop r14;pop r13;pop r12;pop rbx;ret;'
parts.append(cmd)
ks=Ks(KS_ARCH_X86,KS_MODE_64)
asm=';'.join(parts)
blob=bytes(ks.asm(asm,addr=CODE)[0])
entries={k:blob.index(struct.pack('<Q',v))+8 for k,v in markers.items()}
fixups=[]
for target in sorted(TARGETS):
    pattern=struct.pack('<Q',BASE+target);start=0
    while (p:=blob.find(pattern,start))>=0:fixups.append((p,'base',target));start=p+8
start=0
while (p:=blob.find(struct.pack('<Q',CTL),start))>=0:fixups.append((p,'control',0));start=p+8
out=Path(__file__).with_name('native_templates_v3.py')
out.write_text('"""Generated from build_native_v3.py; runtime needs only stdlib."""\nBLOB=bytes.fromhex('+repr(blob.hex())+')\nENTRIES='+repr(entries)+'\nPATCHES='+repr(SPECS)+'\nFIXUPS='+repr(fixups)+'\n',encoding='utf-8')
Path(__file__).with_name('native-v3.asm.txt').write_text(asm.replace(';','\n'),encoding='utf-8')
print(len(blob),entries)
